// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(this)); // owner == test contract; wide domain otherwise
        vm.deal(address(c), amount);

        uint256 before = receiver.balance;
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        assertTrue(receiver.balance == before + amount);
    }
}
